// --- Types & Interfaces ---

export type Currency = 'USD' | 'EUR' | 'GBP' | 'JPY';

export type SyncStatus = 'COMPLETED' | 'PENDING' | 'FAILED' | 'RECONCILING';

export type BridgeDirection = 'CITI_TO_ALPACA' | 'ALPACA_TO_CITI';

export interface CitiAlpacaSyncRecord {
  id: string;
  timestamp: string;
  citiTxRef: string;
  alpacaTxRef: string;
  amount: number;
  currency: Currency;
  fxRate: number;
  direction: BridgeDirection;
  status: SyncStatus;
  complianceHash: string;
  isoMessageId: string;
}

export interface FXRate {
  pair: string;
  rate: number;
  change: number;
}

export interface BridgeRule {
  id: string;
  name: string;
  sourceAccount: string;
  targetAccount: string;
  triggerLimit: number;
  sweepAmount: number;
  currency: Currency;
  active: boolean;
}

export interface BridgeState {
  syncRecords: CitiAlpacaSyncRecord[];
  fxRates: FXRate[];
  rules: BridgeRule[];
  searchTerm: string;
  isReconciling: boolean;
  activeTab: 'sweep' | 'ledger' | 'compliance' | 'rules';
  copiedId: string | null;
  sweepAmount: string;
  sweepCurrency: Currency;
  sweepDirection: BridgeDirection;
  isSubmittingSweep: boolean;
  sweepSuccessMessage: string | null;
  selectedRecord: CitiAlpacaSyncRecord | null;
}

